def transform(grid):
    # Identify separators (rows/cols of 8s)
    H_sep = None
    V_sep = None
    H, W = len(grid), len(grid[0])

    for r in range(H):
        if all(val == 8 for val in grid[r]):
            H_sep = r
            break
    for c in range(W):
        if all(row[c] == 8 for row in grid):
            V_sep = c
            break

    if H_sep is None or V_sep is None:
        return grid

    # Identify background color (most frequent non-8)
    colors = []
    for r in range(H):
        for c in range(W):
            if grid[r][c] != 8:
                colors.append(grid[r][c])
    if colors:
        from collections import Counter
        cnts = Counter(colors)
        bg = max(cnts, key=cnts.get)
    else:
        bg = 4

    regions = [
        [0, H_sep, 0, V_sep],            # TL
        [0, H_sep, V_sep + 1, W],        # TR
        [H_sep + 1, H, 0, V_sep],        # BL
        [H_sep + 1, H, V_sep + 1, W]     # BR
    ]

    source_idx = -1
    empty_indices = []

    # Determine source and empty regions
    for i, (r1, r2, c1, c2) in enumerate(regions):
        is_empty = True
        for r in range(r1, r2):
            for c in range(c1, c2):
                if grid[r][c] != bg:
                    is_empty = False
                    break
            if not is_empty: break
        if is_empty:
            empty_indices.append(i)
        elif source_idx == -1:
            source_idx = i

    # Copy source to empty regions
    if source_idx != -1:
        r1, r2, c1, c2 = regions[source_idx]
        # Prepare output
        output = [row[:] for row in grid]

        # Copy content
        for i_target, indices in enumerate(regions):
            if i_target in empty_indices:
                tr1, tr2, tc1, tc2 = indices
                for r in range(r1, r2):
                    for c in range(c1, c2):
                        r_target = tr1 + (r - r1)
                        c_target = tc1 + (c - c1)
                        output[r_target][c_target] = grid[r][c]

    return output
